package com.bookstore.repository; import com.bookstore.entity.Order; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.math.BigDecimal; import java.util.*; public interface OrderRepository extends JpaRepository<Order,Long>{ List<Order> findByCustomerIdOrderByOrderDateDesc(Long id); @Query("select coalesce(sum(o.total),0) from Order o where o.status <> com.bookstore.entity.OrderStatus.CANCELLED") BigDecimal totalSales(); @Query("select distinct o from Order o left join fetch o.items i left join fetch i.book where o.id=:id") Optional<Order> findDetailedById(@Param("id") Long id); }